-- GENERATED by app/supabase/import/generate-processes-and-properties.py from
-- lofty-processes-and-properties-2026-09-01.xlsx. Edit the workbook or the script, re-run, and commit the diff;
-- do not edit this file by hand.
--
-- Every row here is a cell in Amber's workbook, translated and not guessed at: the
-- format `unknown` is the sheet's own "unknown (no data)"; a null team is a blank
-- department; no process has an expected duration because the sheet gives none. The
-- decisions the script did make — which process a block names, which process an older
-- schedule name refers to, seven spelling fixes — are listed at the end of this file
-- and in `python3 generate-processes-and-properties.py --report`.
--
-- Idempotent: every insert is ON CONFLICT DO NOTHING on its natural key, so a re-run
-- against a database that already carries the workbook changes nothing, and a row
-- somebody has since edited in the app keeps their edit.
-- =============================================================================

-- Template lines are addressed by their schedule number, so parents and dependencies
-- can be wired without knowing the uuid they were given.
create unique index if not exists process_tasks_one_per_import_ref
  on process_tasks (process_id, process_task_import_ref) where process_task_import_ref is not null;

