-- ---------------------------------------------------------------------- proof
do $$
declare n integer;
begin
  select count(*) into n from processes where process_import_ref like 'Processes!%';
  if n < 49 then raise exception 'processes: expected at least 49 seeded rows, found %', n; end if;
  select count(*) into n from property_defs where property_def_import_ref like 'Properties!%';
  if n < 174 then raise exception 'property_defs: expected at least 174 seeded rows, found %', n; end if;
  select count(*) into n from process_dependencies where true;
  if n < 48 then raise exception 'process_dependencies: expected at least 48 seeded rows, found %', n; end if;
  select count(*) into n from process_tasks where process_task_import_ref is not null;
  if n < 107 then raise exception 'process_tasks: expected at least 107 seeded rows, found %', n; end if;
  select count(*) into n from process_task_dependencies where true;
  if n < 99 then raise exception 'process_task_dependencies: expected at least 99 seeded rows, found %', n; end if;
  raise notice 'ok  workbook seeded: 49 processes, 174 properties, 48 dependencies, 107 schedule lines';
end $$;

